package net.ludovicoflaviano.bettersfp.production;
import net.ludovicoflaviano.bettersfp.data.*;import org.bukkit.*;import org.bukkit.plugin.java.JavaPlugin;import java.util.*;import java.util.concurrent.ThreadLocalRandom;
public final class ProductionTask implements Runnable {private final JavaPlugin plugin;private final SpawnerStore store;public ProductionTask(JavaPlugin p,SpawnerStore s){plugin=p;store=s;}public void run(){int base=plugin.getConfig().getInt("settings.storage-base-capacity",256),per=plugin.getConfig().getInt("settings.storage-capacity-per-level",256);for(SpawnerData d:new ArrayList<>(store.all().values())){Location l=SpawnerStore.location(d.key);if(l==null||!l.isChunkLoaded()||l.getBlock().getType()!=Material.SPAWNER)continue;int cap=d.capacity(base,per);if(d.itemCount()<cap)addDrops(d,cap);d.storedXp+=Math.round(3*d.stack*(1+d.yieldLevel*.20));}store.save();}
 private void addDrops(SpawnerData d,int cap){var s=plugin.getConfig().getConfigurationSection("drops."+d.entity);if(s==null)return;double mult=1+d.yieldLevel*plugin.getConfig().getDouble("upgrades.yield.output-multiplier-per-level",.20);for(String name:s.getKeys(false)){if(d.itemCount()>=cap)break;Material m;try{m=Material.valueOf(name);}catch(Exception e){continue;}String[] q=s.getString(name,"1-1").split("-");int lo=parse(q,0,1),hi=parse(q,1,lo);int amount=(int)Math.round(ThreadLocalRandom.current().nextInt(lo,hi+1)*mult*d.stack);if(amount>0)d.items.merge(m,Math.min(amount,cap-d.itemCount()),Integer::sum);}}
 private int parse(String[] a,int i,int d){try{return i<a.length?Integer.parseInt(a[i]):d;}catch(Exception e){return d;}}
}
